//! S1 benchmark: loads a file generated by `cargo xtask gen-data` with the store and with two
//! reference points (serde alone, and `serde_json::Value`), and reports memory, loading, access and navigation, and modification measures.
//!
//! ```text
//! cargo run --release -p ortelia-service --example s1 -- all ~/s1/reseau-10M.json
//! ```
//!
//! - `all <file> [--only floor,v0,store]`: runs every case in a process of its own (the program
//!   runs itself again), so that the memory peak of a case does not skew the next one, then
//!   prints a Markdown table.
//! - `case <implementation> <mode> <file>`: runs one case and prints one line per measure.
//! - `stats <file>`: prints the number of objects per class.
//!
//! Implementations: `floor` (serde's `IgnoredAny`, no construction), `v0` (`serde_json::Value`,
//! the reference point), `store` (the store chosen by the S1 trial, `docs/essais/s1-stockage.md`). Modes: `stream` (read as it comes),
//! `buffer` (file read whole first), `count` (stream, allocations counted).

mod access;
mod counting_alloc;
mod edit;
mod memory;
mod report;

use std::fs::File;
use std::hint::black_box;
use std::io::{self, BufReader};
use std::path::Path;
use std::process::{Command, ExitCode, Stdio};
use std::sync::Arc;
use std::time::Instant;

use ortelia_model::metamodel::{Model, ModelFile};
use ortelia_service::json::{read_json, read_json_slice};
use serde::Deserialize;
use serde::de::IgnoredAny;

use access::{Inventory, Network, Settings};
use report::{Measure, Row};

const USAGE: &str = "usage:
  s1 all <file> [--only floor,v0,store]
  s1 case <floor|v0|store> <stream|buffer|count> <file>
  s1 stats <file>";

/// The cases run by `all`, in order.
const CASES: &[(&str, &str)] = &[
    ("floor", "stream"),
    ("floor", "buffer"),
    ("v0", "stream"),
    ("v0", "buffer"),
    ("store", "stream"),
    ("store", "buffer"),
    ("store", "count"),
];

/// Read buffer of the streams, as in the JSON reader.
const BUFFER_SIZE: usize = 64 * 1024;

const MIB: f64 = 1024.0 * 1024.0;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let args: Vec<&str> = args.iter().map(String::as_str).collect();
    let result = match args.as_slice() {
        ["all", file] => run_all(file, None),
        ["all", file, "--only", only] => run_all(file, Some(only.split(',').collect())),
        ["case", implementation, mode, file] => {
            run_case(implementation, mode, Path::new(file), &Settings::full()).map(|measures| {
                for measure in measures {
                    println!("{}", measure.to_line());
                }
            })
        }
        ["stats", file] => stats(Path::new(file)),
        _ => {
            eprintln!("{USAGE}");
            return ExitCode::from(2);
        }
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("error: {message}");
            ExitCode::FAILURE
        }
    }
}

/// Runs every case in a process of its own and prints the report.
fn run_all(file: &str, only: Option<Vec<&str>>) -> Result<(), String> {
    // An unknown name would silently skip every case.
    if let Some(unknown) = only.iter().flatten().find(|name| {
        !CASES
            .iter()
            .any(|(implementation, _)| implementation == *name)
    }) {
        return Err(format!("--only: unknown implementation `{unknown}`"));
    }
    let size = std::fs::metadata(file)
        .map_err(|e| format!("{file}: {e}"))?
        .len();
    // Read the file once, so that every case finds it in the page cache.
    let mut reader = File::open(file).map_err(|e| format!("{file}: {e}"))?;
    io::copy(&mut reader, &mut io::sink()).map_err(|e| format!("{file}: {e}"))?;

    let exe = std::env::current_exe().map_err(|e| format!("cannot find the program: {e}"))?;
    let mut rows = Vec::new();
    let mut failed = false;
    for &(implementation, mode) in CASES {
        if only
            .as_ref()
            .is_some_and(|only| !only.contains(&implementation))
        {
            continue;
        }
        eprintln!("s1: {implementation} {mode}");
        let output = Command::new(&exe)
            .args(["case", implementation, mode, file])
            .stderr(Stdio::inherit())
            .output()
            .map_err(|e| format!("cannot run a case: {e}"))?;
        let measures: Vec<Measure> = String::from_utf8_lossy(&output.stdout)
            .lines()
            .filter_map(Measure::from_line)
            .collect();
        let row = |measure| Row {
            implementation: implementation.to_owned(),
            mode: mode.to_owned(),
            measure,
        };
        if output.status.success() && !measures.is_empty() {
            rows.extend(measures.into_iter().map(|m| row(Some(m))));
        } else {
            failed = true;
            rows.push(row(None));
        }
    }
    let title = format!("{file} ({:.1} Mio)", size as f64 / MIB);
    println!("{}", report::markdown(&title, &rows));
    if failed {
        Err("at least one case failed".to_owned())
    } else {
        Ok(())
    }
}

/// The compiled test model.
fn network_model() -> Result<Arc<Model>, String> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../examples/reseau-meteo/reseau.model.json"
    );
    let text = std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
    let file = ModelFile::parse(&text).map_err(|e| format!("{path}: {e}"))?;
    Model::compile(&[file])
        .map(Arc::new)
        .map_err(|e| format!("{path}: {e}"))
}

/// Runs one case and returns its measures.
fn run_case(
    implementation: &str,
    mode: &str,
    path: &Path,
    settings: &Settings,
) -> Result<Vec<Measure>, String> {
    let file_mib = std::fs::metadata(path)
        .map_err(|e| format!("{}: {e}", path.display()))?
        .len() as f64
        / MIB;
    match (implementation, mode) {
        ("floor", "stream" | "buffer") => parse_only::<IgnoredAny>(mode, path, file_mib),
        ("v0", "stream" | "buffer") => parse_only::<serde_json::Value>(mode, path, file_mib),
        ("store", _) => store_case(mode, path, file_mib, settings),
        _ => Err(format!("unknown case `{implementation} {mode}`")),
    }
}

/// The floor and V0: serde alone, into `T` (nothing for `IgnoredAny`, a tree for `Value`).
fn parse_only<T: for<'de> Deserialize<'de>>(
    mode: &str,
    path: &Path,
    file_mib: f64,
) -> Result<Vec<Measure>, String> {
    let error = |e: &dyn std::fmt::Display| format!("{}: {e}", path.display());
    let mut measures = Vec::new();
    let start = Instant::now();
    let value: T = if mode == "stream" {
        let reader =
            BufReader::with_capacity(BUFFER_SIZE, File::open(path).map_err(|e| error(&e))?);
        let mut de = serde_json::Deserializer::from_reader(reader);
        let value = T::deserialize(&mut de).map_err(|e| error(&e))?;
        de.end().map_err(|e| error(&e))?;
        value
    } else {
        let bytes = std::fs::read(path).map_err(|e| error(&e))?;
        measures.push(Measure::new(
            "C0",
            "lecture du fichier en mémoire",
            "ms",
            Some(millis(start)),
        ));
        // `bytes` is dropped at the end of this block: memory after loading excludes it.
        serde_json::from_slice(&bytes).map_err(|e| error(&e))?
    };
    measures.push(Measure::new(
        "C1",
        "temps de chargement",
        "ms",
        Some(millis(start)),
    ));
    measures.extend(memory_measures(file_mib));
    black_box(&value);
    Ok(measures)
}

/// The store: loading, memory, and in stream mode the access and modification measures.
fn store_case(
    mode: &str,
    path: &Path,
    file_mib: f64,
    settings: &Settings,
) -> Result<Vec<Measure>, String> {
    let model = network_model()?;
    let root = model.class_id("Reseau").ok_or("no class Reseau")?;
    let error = |e: &dyn std::fmt::Display| format!("{}: {e}", path.display());
    let mut measures = Vec::new();
    let start = Instant::now();
    let mut store = match mode {
        "stream" => {
            let file = File::open(path).map_err(|e| error(&e))?;
            read_json(file, model.clone(), root).map_err(|e| error(&e))?
        }
        "count" => {
            let file = File::open(path).map_err(|e| error(&e))?;
            counting_alloc::start();
            let store = read_json(file, model.clone(), root);
            let (count, bytes) = counting_alloc::stop();
            black_box(&store.map_err(|e| error(&e))?);
            return Ok(vec![
                Measure::new(
                    "M3",
                    "nombre d'allocations pendant le chargement",
                    "allocations",
                    Some(count as f64),
                ),
                Measure::new(
                    "M3o",
                    "octets alloués pendant le chargement",
                    "Mio",
                    Some(bytes as f64 / MIB),
                ),
            ]);
        }
        "buffer" => {
            let bytes = std::fs::read(path).map_err(|e| error(&e))?;
            measures.push(Measure::new(
                "C0",
                "lecture du fichier en mémoire",
                "ms",
                Some(millis(start)),
            ));
            read_json_slice(&bytes, model.clone(), root).map_err(|e| error(&e))?
        }
        _ => return Err(format!("unknown mode `{mode}`")),
    };
    measures.push(Measure::new(
        "C1",
        "temps de chargement",
        "ms",
        Some(millis(start)),
    ));
    measures.extend(memory_measures(file_mib));
    if mode == "stream" {
        let net = Network::new(&model);
        let inventory = Inventory::new(&store, &net);
        measures.extend(access::measure_all(&mut store, &net, &inventory, settings));
        measures.extend(edit::measure_all(&mut store, &net, &inventory, settings).measures);
    }
    // Keeps the store alive until the measures are complete.
    black_box(&store);
    Ok(measures)
}

/// M1 and M2, right after loading.
fn memory_measures(file_mib: f64) -> Vec<Measure> {
    let resident = memory::resident_mib();
    vec![
        Measure::new(
            "M1",
            "pic de mémoire du processus (VmHWM)",
            "Mio",
            memory::peak_mib(),
        ),
        Measure::new("M2", "mémoire après chargement (VmRSS)", "Mio", resident),
        Measure::new(
            "M2r",
            "mémoire après chargement, rapportée à la taille du fichier",
            "×",
            resident.map(|r| r / file_mib),
        ),
    ]
}

fn millis(start: Instant) -> f64 {
    start.elapsed().as_secs_f64() * 1e3
}

/// Prints the number of objects per class of a file.
fn stats(path: &Path) -> Result<(), String> {
    let model = network_model()?;
    let root = model.class_id("Reseau").ok_or("no class Reseau")?;
    let file = File::open(path).map_err(|e| format!("{}: {e}", path.display()))?;
    let store =
        read_json(file, model.clone(), root).map_err(|e| format!("{}: {e}", path.display()))?;
    let mut counts = vec![0usize; model.classes().len()];
    let mut stack = vec![store.root().ok_or("no root")?];
    while let Some(obj) = stack.pop() {
        let class = store.class_of(obj);
        counts[class.index()] += 1;
        for reference in model.class(class).references() {
            stack.extend_from_slice(store.children(obj, reference.id()));
        }
    }
    println!("| Classe | Objets |\n|---|---:|");
    for (class, count) in model.classes().iter().zip(&counts) {
        if *count > 0 {
            println!("| {} | {count} |", class.name());
        }
    }
    println!("| **Total** | {} |", counts.iter().sum::<usize>());
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use ortelia_model::store::Store;

    fn example() -> std::path::PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../examples/reseau-meteo/reseau-exemple.json")
    }

    /// Settings small enough for a debug build, large enough to cover the example file.
    fn small() -> Settings {
        Settings {
            passes: 3,
            a1_reads: 1_000,
            a5_walks: 100,
            a6_windows: 10,
            a7_edits: 10,
            e1_sets: 1_000,
            e2_list: 1_000,
            e2_objects: 10,
            e4_cells: 1_000,
        }
    }

    fn codes(measures: &[Measure]) -> Vec<&str> {
        measures.iter().map(|m| m.code.as_str()).collect()
    }

    fn assert_all_values(measures: &[Measure]) {
        for measure in measures {
            let memory =
                measure.code.starts_with('M') && measure.code != "M3" && measure.code != "M3o";
            let memory_unavailable = memory && !cfg!(target_os = "linux");
            assert_eq!(measure.value.is_some(), !memory_unavailable, "{measure:?}");
            if let Some(value) = measure.value {
                assert!(
                    value.is_finite() && (value >= 0.0 || measure.code == "E1m"),
                    "{measure:?}"
                );
            }
        }
    }

    /// Every loading case gives its measures on the example file (task 5.2).
    #[test]
    fn loading_cases() {
        let path = example();
        for implementation in ["floor", "v0"] {
            let stream = run_case(implementation, "stream", &path, &small()).expect(implementation);
            assert_eq!(codes(&stream), ["C1", "M1", "M2", "M2r"]);
            assert_all_values(&stream);
            let buffer = run_case(implementation, "buffer", &path, &small()).expect(implementation);
            assert_eq!(codes(&buffer), ["C0", "C1", "M1", "M2", "M2r"]);
            assert_all_values(&buffer);
        }
        let buffer = run_case("store", "buffer", &path, &small()).expect("store");
        assert_eq!(codes(&buffer), ["C0", "C1", "M1", "M2", "M2r"]);
        assert_all_values(&buffer);
        let count = run_case("store", "count", &path, &small()).expect("store");
        assert_eq!(codes(&count), ["M3", "M3o"]);
        assert_all_values(&count);
        assert!(count[0].value.expect("M3") > 0.0);
        assert!(run_case("nope", "stream", &path, &small()).is_err());
    }

    /// `--only` refuses a name that is not an implementation, instead of running nothing.
    #[test]
    fn unknown_implementation_in_only() {
        let error = run_all("unused.json", Some(vec!["store", "nope"])).expect_err("unknown");
        assert!(error.contains("`nope`"), "{error}");
    }

    /// The stream case of the store gives every measure (tasks 5.4 and 5.5).
    #[test]
    fn stream_case_gives_every_measure() {
        let measures = run_case("store", "stream", &example(), &small()).expect("store");
        assert_eq!(
            codes(&measures),
            [
                "C1", "M1", "M2", "M2r", "A1", "A2", "A3", "A4", "A5", "A6", "A7", "E1", "E1m",
                "E2", "E4", "E3"
            ]
        );
        assert_all_values(&measures);
    }

    fn loaded() -> (Store, Network, Inventory) {
        let model = network_model().expect("model");
        let root = model.class_id("Reseau").expect("Reseau");
        let file = File::open(example()).expect("example");
        let store = read_json(file, model.clone(), root).unwrap_or_else(|e| panic!("{e}"));
        let net = Network::new(&model);
        let inventory = Inventory::new(&store, &net);
        (store, net, inventory)
    }

    /// A1 to A7 cover the example file (task 5.4).
    #[test]
    fn access_measures() {
        let (mut store, net, inventory) = loaded();
        assert_eq!((inventory.stations.len(), inventory.readings.len()), (2, 6));
        assert_eq!(
            (
                inventory.points.len(),
                inventory.corners.len(),
                inventory.zones.len()
            ),
            (17, 12, 2)
        );
        let measures = access::measure_all(&mut store, &net, &inventory, &small());
        assert_eq!(codes(&measures), ["A1", "A2", "A3", "A4", "A5", "A6", "A7"]);
        assert!(
            measures.iter().all(|m| m.value.is_some_and(|v| v > 0.0)),
            "{measures:?}"
        );
    }

    /// E1 to E4 cover the example file, and leave the store consistent (task 5.5).
    #[test]
    fn edit_measures() {
        let (mut store, net, inventory) = loaded();
        let settings = small();
        let outcome = edit::measure_all(&mut store, &net, &inventory, &settings);
        assert_eq!(codes(&outcome.measures), ["E1", "E1m", "E2", "E4", "E3"]);
        assert!(
            outcome
                .measures
                .iter()
                .all(|m| m.code == "E1m" || m.value.is_some_and(|v| v > 0.0))
        );

        // The deleted stations are no longer alive, with their subtrees.
        assert_eq!(outcome.e3_deleted, inventory.stations);
        assert!(outcome.e3_deleted.iter().all(|&s| !store.is_alive(s)));
        assert!(inventory.readings.iter().all(|&r| !store.is_alive(r)));
        let root = store.root().expect("root");
        assert!(store.children(root, net.stations).is_empty());

        // The cells created are in their zone, with their 4 corners.
        let zone = outcome.e4_zone.expect("zone");
        assert_eq!(outcome.e4_cells.len(), settings.passes * settings.e4_cells);
        let cells = store.children(zone, net.cells);
        assert_eq!(cells.len(), 2 + outcome.e4_cells.len());
        assert_eq!(&cells[2..], outcome.e4_cells.as_slice());
        for &cell in &outcome.e4_cells {
            assert_eq!(store.container(cell).map(|c| c.0), Some(zone));
            assert_eq!(store.children(cell, net.corners).len(), 4);
        }
        // The zone of E2 is gone; the zones of the file remain.
        assert_eq!(store.children(root, net.zones), inventory.zones);
    }
}
